
"use client";

import { useState } from "react";

export default function Home() {
  const [files, setFiles] = useState<File[]>([]);
  const [loading, setLoading] = useState(false);

  const handleFiles = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      setFiles(Array.from(e.target.files));
    }
  };

  const sendToAPI = async (action: string) => {
    if (files.length === 0) {
      alert("Seleccioná al menos un PDF");
      return;
    }

    setLoading(true);

    try {
      const formData = new FormData();

      files.forEach((file) => {
        formData.append("files", file);
      });

      formData.append("action", action);

      const res = await fetch("/api/pdf", {
        method: "POST",
        body: formData,
      });

      if (!res.ok) {
        throw new Error("Error procesando PDF");
      }

      const blob = await res.blob();

      const url = window.URL.createObjectURL(blob);

      const a = document.createElement("a");
      a.href = url;
      a.download = "resultado.pdf";
      a.click();

      window.URL.revokeObjectURL(url);
    } catch (error) {
      console.error(error);
      alert("Ocurrió un error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <main className="min-h-screen bg-gray-950 text-white flex flex-col items-center justify-center p-10">

      <h1 className="text-4xl font-bold mb-10">📄 PDF Toolkit</h1>

      <input
        type="file"
        multiple
        accept="application/pdf"
        onChange={handleFiles}
        className="mb-6"
      />

      {files.length > 0 && (
        <div className="mb-6 text-sm text-gray-300">
          <p className="mb-2">Archivos seleccionados:</p>

          <ul>
            {files.map((file) => (
              <li key={file.name}>
                {file.name}
              </li>
            ))}
          </ul>
        </div>
      )}

      <div className="bg-gray-900 p-8 rounded-2xl w-full max-w-xl shadow-lg">

        <div className="grid grid-cols-2 gap-4">
          <button
            disabled={loading}
            onClick={() => sendToAPI("merge")}
            className="bg-blue-600 hover:bg-blue-700 p-3 rounded-xl disabled:opacity-50"
          >
            {loading ? "Procesando..." : "Unir PDFs"}
          </button>

          <button
            disabled={loading}
            onClick={() => sendToAPI("split")}
            className="bg-purple-600 hover:bg-purple-700 p-3 rounded-xl disabled:opacity-50"
          >
            {loading ? "Procesando..." : "Dividir PDF"}
          </button>

          <button
            disabled={loading}
            onClick={() => sendToAPI("rotate")}
            className="bg-green-600 hover:bg-green-700 p-3 rounded-xl disabled:opacity-50"
          >
            {loading ? "Procesando..." : "Rotar PDF"}
          </button>

          <button
            disabled={loading}
            onClick={() => sendToAPI("compress")}
            className="bg-red-600 hover:bg-red-700 p-3 rounded-xl disabled:opacity-50"
          >
            {loading ? "Procesando..." : "Comprimir"}
          </button>
          
        </div>

      </div>

    </main>
  );
}
